function useWineryBatchSettings(farmId) {
  const qc = useQueryClient();
  const { toast } = useToast();
  const viticultureActive = useIsViticultureActive(farmId);
  const q = useQuery({
    queryKey: ["winery-batch-settings", farmId],
    queryFn: async () => await fetchWineryJson(`farms/${farmId}/winery-batch-settings`),
    enabled: !!farmId && viticultureActive,
    staleTime: 3e4
  });
  const save = useMutation({
    mutationFn: async (body) => {
      const r = await fetch(apiUrl(`farms/${farmId}/winery-batch-settings`), {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify(body)
      });
      if (!r.ok) {
        const e = await r.json().catch(() => ({}));
        throw new Error(e.error || "Save failed");
      }
      return r.json();
    },
    onSuccess: () => qc.invalidateQueries({ queryKey: ["winery-batch-settings", farmId] }),
    onError: () => toast({ title: "Save failed", variant: "destructive" })
  });
  return { data: q.data, isLoading: q.isLoading, save };
}
